/**
 * Función para agregar iconos de redes sociales reales al PDF de cotización
 */
export async function addSocialIconsToPDF(
  doc: any,
  pageWidth: number,
  pageHeight: number,
) {
  const footerY = pageHeight - 25;
  const iconSize = 10;
  const spacing = iconSize + 3;

  // Obtener las imágenes de redes sociales
  const icons = await getSocialIcons();

  // Posición inicial (alineado a la derecha)
  let currentX = pageWidth - spacing * 4 - 10;
  const iconY = footerY - iconSize / 2;

  // Función auxiliar para dibujar iconos circulares como fallback
  const drawCircularIcon = (
    x: number,
    y: number,
    text: string,
    bgColor: number[] = [0, 0, 0],
    textColor: number[] = [255, 255, 255],
  ) => {
    // Guardar configuración actual
    const currentTextColor = doc.getTextColor();

    // Dibujar círculo de fondo
    doc.setFillColor(...bgColor);
    doc.circle(x + iconSize / 2, y + iconSize / 2, iconSize / 2, "F");

    // Configurar texto
    doc.setTextColor(...textColor);
    doc.setFontSize(6);

    // Calcular posición del texto para centrarlo
    const textWidth = doc.getTextWidth(text);
    const textX = x + (iconSize - textWidth) / 2;
    const textY = y + iconSize / 2 + 1.5;

    doc.text(text, textX, textY);
  };

  // Facebook - usar imagen real
  try {
    if (icons.facebook) {
      doc.addImage(icons.facebook, "JPEG", currentX, iconY, iconSize, iconSize);
    } else {
      drawCircularIcon(currentX, iconY, "f", [59, 89, 152], [255, 255, 255]);
    }
    currentX += spacing;
  } catch (e) {
    drawCircularIcon(currentX, iconY, "f", [59, 89, 152], [255, 255, 255]);
    currentX += spacing;
  }

  // Instagram - usar imagen real
  try {
    if (icons.instagram) {
      doc.addImage(
        icons.instagram,
        "JPEG",
        currentX,
        iconY,
        iconSize,
        iconSize,
      );
    } else {
      drawCircularIcon(currentX, iconY, "i", [225, 48, 108]);
    }
    currentX += spacing;
  } catch (e) {
    drawCircularIcon(currentX, iconY, "i", [225, 48, 108]);
    currentX += spacing;
  }

  // TikTok - usar imagen real
  try {
    if (icons.tiktok) {
      doc.addImage(icons.tiktok, "JPEG", currentX, iconY, iconSize, iconSize);
    } else {
      drawCircularIcon(currentX, iconY, "T", [0, 0, 0]);
    }
    currentX += spacing;
  } catch (e) {
    drawCircularIcon(currentX, iconY, "T", [0, 0, 0]);
    currentX += spacing;
  }

  // MercadoLibre - usar imagen real
  try {
    if (icons.mercadolibre) {
      doc.addImage(
        icons.mercadolibre,
        "JPEG",
        currentX,
        iconY,
        iconSize,
        iconSize,
      );
    } else {
      drawCircularIcon(currentX, iconY, "M", [255, 242, 0], [0, 0, 0]);
    }
  } catch (e) {
    drawCircularIcon(currentX, iconY, "M", [255, 242, 0], [0, 0, 0]);
  }

  // Restaurar configuración del documento
  doc.setTextColor(0, 0, 0);
  doc.setFontSize(10);
}

function getSocialIcons() {
  return {
    // Facebook - imagen real
    facebook:
      "data:image/jpeg;base64,",

    // Instagram - imagen real
    instagram:
      "data:image/jpeg;base64,",

    // TikTok - imagen real de tu archivo TT1(1)_1751252036053.jpg
    tiktok:
      "data:image/png;base64,",

    // MercadoLibre - imagen real de tu archivo mercadolibre_1751252036053.jpg
    mercadolibre: `data:image/jpeg;base64,${await(async () => {
      try {
        const response = await fetch(
          "/attached_assets/mercadolibre_1751252036053.jpg",
        );
        const arrayBuffer = await response.arrayBuffer();
        const base64 = btoa(
          String.fromCharCode(...new Uint8Array(arrayBuffer)),
        );
        return base64;
      } catch (error) {
        // Fallback a una cadena base64 existente si hay error
        return "";
      }
    })()}`,
  };
}
